package co.aplomo.servicio;
import co.aplomo.dao.*;import co.aplomo.modelo.*;import co.aplomo.soporte.*;import co.aplomo.db.Sql;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.*;import java.nio.file.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** RF-024: filtros combinados, orden, datos invisibles antes de finalizar y cero modificaciones al consultar. */
class ConsultasTest extends BasePrueba {
    @TempDir Path fotos;EscenarioConsultas e;Consultas consultas;
    @BeforeEach void escenario()throws Exception{e=new EscenarioConsultas(this,fotos);consultas=e.consultas;}
    @ParameterizedTest @EnumSource(SeccionConsulta.class) void cadaSeccionSoloDevuelveEmpresaAutorizada(SeccionConsulta seccion)throws Exception{var p=consultas.listar(cuenta(usuario),seccion,Map.of());assertFalse(p.filas().isEmpty());assertTrue(p.filas().stream().allMatch(x->x.valor("empresa").equals(""+empresa)));assertTrue(p.catalogos().values().stream().flatMap(Collection::stream).allMatch(x->x.empresa()==empresa));assertFalse(p.filas().toString().contains("Empresa ajena QA"));assertThrows(SecurityException.class,()->consultas.listar(cuenta(usuario),seccion,Map.of("empresa",""+e.empresaB)));}
    @Test void todosLosFiltrosDeEvaluacionSeCombinan()throws Exception{var f=new HashMap<String,String>();f.put("empresa",""+e.empresaA);f.put("sede",""+e.sedeA);f.put("salon",""+e.salonA);f.put("area",""+e.areaA);f.put("cargo",""+e.cargoA);f.put("numero","3");f.put("desde","2026-11-10");f.put("hasta","2026-11-10");f.put("puntaje","7");f.put("color","ROJO");f.put("nivel","4");f.put("estado","FINALIZADA");var p=consultas.listar(cuenta(usuario),SeccionConsulta.EVALUACIONES,f);assertEquals(1,p.filas().size());assertEquals(e.evalRojo,p.filas().get(0).id());f.put("puntaje","2");assertTrue(consultas.listar(cuenta(usuario),SeccionConsulta.EVALUACIONES,f).filas().isEmpty());}
    @Test void usuarioVeTodasSusReservasConCancelacionPeroNoResultadosAbiertos()throws Exception{assertEquals(4,consultas.listar(cuenta(usuario),SeccionConsulta.RESERVAS,Map.of()).filas().size());var r=new Reservas(tx,reloj).consultar(cuenta(usuario),e.reservaCancelada);assertEquals("La empresa solicitó otro horario.",r.reserva().motivo());assertEquals(1,consultas.listar(cuenta(usuario),SeccionConsulta.VISITAS,Map.of()).filas().size());assertEquals(2,consultas.listar(cuenta(usuario),SeccionConsulta.EVALUACIONES,Map.of()).filas().size());assertThrows(SecurityException.class,()->consultas.evaluacion(cuenta(usuario),e.evalAbierta));assertThrows(SecurityException.class,()->consultas.listar(cuenta(usuario),SeccionConsulta.EVALUACIONES,Map.of("visita",""+e.visitaAbierta)));assertThrows(SecurityException.class,()->consultas.listar(cuenta(usuario),SeccionConsulta.PENDIENTES,Map.of("estado","TODOS","evaluacion",""+e.evalAbierta)));assertThrows(SecurityException.class,()->consultas.listar(cuenta(usuario),SeccionConsulta.SUGERENCIAS,Map.of("evaluacion",""+e.evalAbierta)));}
    @Test void puntajeDelPuestoSeOcultaHastaFinalizarInclusoSiHayUnVerdeAnterior()throws Exception{var empresas=new Empresas(tx);assertEquals(7,empresas.puesto(cuenta(admin),e.puesto1).puntaje());assertEquals(2,empresas.puesto(cuenta(usuario),e.puesto1).puntaje());assertNull(empresas.puesto(cuenta(usuario),e.puesto2).puntaje());var p=consultas.listar(cuenta(usuario),SeccionConsulta.PUESTOS,Map.of("orden","puntaje","direccion","desc")).filas();assertEquals(e.puesto3,p.get(0).id());assertEquals("2",p.stream().filter(x->x.id()==e.puesto1).findFirst().orElseThrow().valor("puntaje"));assertEquals("",p.get(p.size()-1).valor("puntaje"));new Visitas(tx,reloj).finalizar(cuenta(admin),e.visitaAbierta,"");assertEquals(7,empresas.puesto(cuenta(usuario),e.puesto1).puntaje());assertEquals(7,empresas.puesto(cuenta(usuario),e.puesto2).puntaje());assertNotNull(consultas.evaluacion(cuenta(usuario),e.evalAbierta));}
    @Test void busquedaIgnoraMayusculasTildesYNoInterpretaSql()throws Exception{var p=consultas.listar(cuenta(usuario),SeccionConsulta.AREAS,Map.of("q","PRODUCCION"));assertEquals(1,p.filas().size());assertTrue(consultas.listar(cuenta(usuario),SeccionConsulta.EMPRESAS,Map.of("q","' OR 1=1 --")).filas().isEmpty());assertTrue(consultas.listar(cuenta(usuario),SeccionConsulta.RESERVAS,Map.of("q","otro horario")).filas().stream().allMatch(x->x.id()==e.reservaCancelada));}
    @Test void ordenaNumerosEnAmbosSentidosYConservaNulosAlFinal()throws Exception{var asc=consultas.listar(cuenta(usuario),SeccionConsulta.PUESTOS,Map.of("orden","numero","direccion","asc")).filas();var desc=consultas.listar(cuenta(usuario),SeccionConsulta.PUESTOS,Map.of("orden","numero","direccion","desc")).filas();assertEquals(List.of("1","2","3"),asc.stream().map(x->x.valor("numero")).toList());assertEquals(List.of("3","2","1"),desc.stream().map(x->x.valor("numero")).toList());for(String direccion:List.of("asc","desc"))assertEquals(e.puesto2,consultas.listar(cuenta(usuario),SeccionConsulta.PUESTOS,Map.of("orden","puntaje","direccion",direccion)).filas().get(2).id());}
    @ParameterizedTest @ValueSource(strings={"empresa","sede","salon","area","cargo"}) void catalogosAjenosSeDenieganTambienPorParametro(String key)throws Exception{int id=switch(key){case "empresa"->e.empresaB;case "sede"->e.sedeB;case "salon"->e.salonB;case "area"->e.areaB;default->e.cargoB;};assertThrows(SecurityException.class,()->consultas.listar(cuenta(usuario),SeccionConsulta.EVALUACIONES,Map.of(key,""+id)));}
    @ParameterizedTest @ValueSource(strings={"orden","direccion","puntaje","nivel","numero","desde","estado","color"}) void rechazaFiltrosInvalidos(String key)throws Exception{String valor=switch(key){case "puntaje"->"8";case "nivel"->"5";case "numero"->"-1";case "desde"->"no-fecha";default->"x; DROP TABLE";};assertThrows(IllegalArgumentException.class,()->consultas.listar(cuenta(admin),SeccionConsulta.EVALUACIONES,Map.of(key,valor)));}
    @Test void consultasNoCambianDatosYLasFechasSinCoincidenciasDevuelvenCero()throws Exception{int antes=Sql.uno(con,"SELECT COUNT(*) FROM bitacora",r->r.getInt(1));for(var s:SeccionConsulta.values())consultas.listar(cuenta(usuario),s,Map.of("q","inexistente"));assertEquals(antes,Sql.<Integer>uno(con,"SELECT COUNT(*) FROM bitacora",r->r.getInt(1)));assertTrue(consultas.listar(cuenta(usuario),SeccionConsulta.EVALUACIONES,Map.of("desde","2026-11-11")).filas().isEmpty());assertThrows(IllegalArgumentException.class,()->consultas.listar(cuenta(admin),SeccionConsulta.EVALUACIONES,Map.of("desde","2026-11-12","hasta","2026-11-10")));}
}
